(function(root){let token='',available=false,seq=0,controller=null;const A={enabled:false,async status(){if(location.protocol==='file:')return {mode:'mock'};try{const r=await fetch('/api/status');const d=await r.json();token=d.csrf||'';available=d.mode==='available';return d}catch{return {mode:'mock'}}},cancel(){seq++;controller?.abort();controller=null;},async request(kind,data,key){if(!A.enabled||!available)return null;A.cancel();const generation=seq;controller=new AbortController();try{const r=await fetch('/api/'+kind,{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json','x-csrf-token':token,'idempotency-key':key},body:JSON.stringify({...data,consent:true}),signal:controller.signal});if(!r.ok)return null;const d=await r.json();return generation===seq&&d.mode==='ai'?d.result:null}catch{return null}finally{if(generation===seq)controller=null}},get available(){return available}};root.PandaAI=A;})(window);
